public class DatabaseConnection {
    // volatile ensures that multiple threads handle the uniqueInstance variable correctly
    private static volatile DatabaseConnection instance;

    // Private constructor prevents instantiation from outside
    private DatabaseConnection() {
        // initialization code
    }

    public static DatabaseConnection getInstance() {
        if (instance == null) { // First check (no locking)
            synchronized (DatabaseConnection.class) {
                if (instance == null) { // Second check (with locking)
                    instance = new DatabaseConnection();
                }
            }
        }
        return instance;
    }
}

// 1. The Product Interface
public interface Notification {
    void notifyUser();
}

// 2. Concrete Products
public class SMSNotification implements Notification {
    public void notifyUser() { System.out.println("Sending an SMS"); }
}
public class EmailNotification implements Notification {
    public void notifyUser() { System.out.println("Sending an Email"); }
}

// 3. The Creator (Abstract Factory)
public abstract class NotificationService {
    // The Factory Method
    protected abstract Notification createNotification();

    public void sendNotification() {
        Notification notification = createNotification();
        notification.notifyUser();
    }
}

// 4. Concrete Creators
public class SMSNotificationService extends NotificationService {
    @Override
    protected Notification createNotification() {
        return new SMSNotification();
    }
}

// Client Usage
NotificationService service = new SMSNotificationService();
service.sendNotification(); // Outputs: Sending an SMS

public class User {
    private final String firstName; // Required
    private final String lastName;  // Required
    private final int age;          // Optional
    private final String phone;     // Optional

    // Private constructor takes the builder
    private User(UserBuilder builder) {
        this.firstName = builder.firstName;
        this.lastName = builder.lastName;
        this.age = builder.age;
        this.phone = builder.phone;
    }

    public static class UserBuilder {
        private final String firstName;
        private final String lastName;
        private int age;
        private String phone;

        // Required parameters go in builder constructor
        public UserBuilder(String firstName, String lastName) {
            this.firstName = firstName;
            this.lastName = lastName;
        }

        // Optional setters return the builder itself (fluent interface)
        public UserBuilder age(int age) {
            this.age = age;
            return this;
        }

        public UserBuilder phone(String phone) {
            this.phone = phone;
            return this;
        }

        public User build() {
            return new User(this);
        }
    }
}

// Usage
User user = new User.UserBuilder("John", "Doe")
    .age(30)
    .phone("123-456-7890")
    .build();

// 1. Strategy Interface
public interface PaymentStrategy {
    void pay(int amount);
}

// 2. Concrete Strategies
public class CreditCardStrategy implements PaymentStrategy {
    public void pay(int amount) { System.out.println(amount + " paid with Credit Card"); }
}
public class PayPalStrategy implements PaymentStrategy {
    public void pay(int amount) { System.out.println(amount + " paid with PayPal"); }
}

// 3. Context
public class ShoppingCart {
    private PaymentStrategy strategy;

    // Set strategy at runtime
    public void setPaymentStrategy(PaymentStrategy strategy) {
        this.strategy = strategy;
    }

    public void checkout(int amount) {
        strategy.pay(amount);
    }
}

// Usage
ShoppingCart cart = new ShoppingCart();
cart.setPaymentStrategy(new PayPalStrategy());
cart.checkout(100); // Outputs: 100 paid with PayPal

// 1. Observer Interface
public interface WeatherObserver {
    void update(float temperature);
}

// 2. Subject Interface
public interface Subject {
    void attach(WeatherObserver o);
    void detach(WeatherObserver o);
    void notifyObservers();
}

// 3. Concrete Subject
public class WeatherStation implements Subject {
    private List<WeatherObserver> observers = new ArrayList<>();
    private float temperature;

    public void setTemperature(float temp) {
        this.temperature = temp;
        notifyObservers();
    }

    public void attach(WeatherObserver o) { observers.add(o); }
    public void detach(WeatherObserver o) { observers.remove(o); }

    public void notifyObservers() {
        for (WeatherObserver o : observers) {
            o.update(temperature);
        }
    }
}

// 4. Concrete Observer
public class PhoneDisplay implements WeatherObserver {
    public void update(float temperature) {
        System.out.println("Phone Display: Temp is now " + temperature);
    }
}

// Usage
WeatherStation station = new WeatherStation();
PhoneDisplay phone = new PhoneDisplay();
station.attach(phone);
station.setTemperature(25.5f); // Phone automatically prints update
